def nextGreaterElement(nums1, nums2):
    nxt = {}
    stack = []
    for x in nums2:
        while stack and stack[-1] < x:
            nxt[stack.pop()] = x
        stack.append(x)
    return [nxt.get(x, -1) for x in nums1]

brute_force_solution:
def nextGreaterElement(nums1, nums2):
    res = []
    for x in nums1:
        i = nums2.index(x)
        ans = -1
        for y in nums2[i + 1:]:
            if y > x:
                ans = y
                break
        res.append(ans)
    return res

